W = 3
A, G = "Arbeidsrecht", "Gespreksvoering"
# Week 3 heeft geen theoriecollege HRM in de map, dus alleen arbeidsrecht en gespreksvoering.

# ---------- Arbeidsrecht MC ----------
mc("hrm3-a01", W, A, "Wat is de maximale proeftijd bij een arbeidsovereenkomst voor onbepaalde tijd (zonder cao-afwijking)?",
   ["Eén maand", "Twee maanden", "Drie maanden", "Zes maanden"], 1,
   "Art. 7:652 lid 3 BW: bij onbepaalde tijd hoogstens twee maanden. De proeftijd moet bovendien voor beide partijen gelijk zijn (lid 1) en schriftelijk worden aangegaan (lid 2).")
mc("hrm3-a02", W, A, "Dora vertelde bij haar sollicitatie dat ze zwanger is en werd aangenomen. In haar proeftijd is ze een week ziek door zwangerschapsklachten. De werkgever wil haar daarom in de proeftijd ontslaan. Mag dat?",
   ["Ja, in de proeftijd mag de werkgever altijd opzeggen", "Ja, want ziekte in de proeftijd is een geldige reden", "Nee, dat is direct onderscheid op grond van geslacht", "Nee, want in de proeftijd mag alleen de werknemer opzeggen"], 2,
   "Antwoordmodel docent: opzeggen vanwege zwangerschap of een daaraan gekoppelde ziekte is direct onderscheid op grond van geslacht en niet toegestaan. Ook in de proeftijd gelden de gelijkebehandelingsregels.")
mc("hrm3-a03", W, A, "Een facilitair medewerker krijgt een contract voor één jaar. Wat is de maximale proeftijd volgens art. 7:652 lid 4 BW (zonder cao-afwijking)?",
   ["Geen proeftijd", "Eén maand", "Twee maanden", "Drie maanden"], 1,
   "Bij een contract van zes maanden of korter mag er geen proeftijd in. Bij langer dan zes maanden maar korter dan twee jaar is het maximaal één maand, bij twee jaar of langer twee maanden. Controleer de leden in je wettenbundel.")
mc("hrm3-a04", W, A, "Een werkgever en een nieuwe receptionist spreken mondeling een proeftijd van een maand af. Na drie weken zegt de werkgever op 'wegens de proeftijd'. Wat is het probleem?",
   ["Er is geen probleem, de proeftijd mag mondeling", "Een proeftijd moet schriftelijk worden aangegaan, anders geldt hij niet", "De werkgever had eerst het UWV om toestemming moeten vragen", "Een proeftijd mag alleen bij onbepaalde tijd"], 1,
   "Art. 7:652 lid 2 BW: het proeftijdbeding moet schriftelijk. Zonder geldige proeftijd kan de werkgever niet zomaar opzeggen zoals in de proeftijd (art. 7:676 BW).")
mc("hrm3-a05", W, A, "Laura werkt voor onbepaalde tijd als inkoper en krijgt promotie naar teamleider. De werkgever wil in het nieuwe contract opnieuw een proeftijd van twee maanden. Mag dat?",
   ["Nee, een nieuwe proeftijd bij dezelfde werkgever mag nooit", "Ja, als de nieuwe functie duidelijk andere vaardigheden of verantwoordelijkheden vraagt", "Ja, maar alleen een proeftijd van maximaal een week", "Nee, want ze heeft al een contract voor onbepaalde tijd"], 1,
   "Antwoord docent: dat mag. Een nieuwe proeftijd in een opvolgend contract is toegestaan als de nieuwe functie duidelijk andere vaardigheden of verantwoordelijkheden eist (art. 7:652 lid 3 en lid 6 sub b BW). Leidinggeven is zo'n verschil.")
mc("hrm3-a06", W, A, "Welke van deze is géén voorwaarde voor een geldig concurrentiebeding in een contract voor onbepaalde tijd (art. 7:653 lid 1 BW)?",
   ["Het beding is schriftelijk afgesproken", "De werknemer is meerderjarig", "Het beding is goedgekeurd door het UWV", "Het gaat om een arbeidsovereenkomst voor onbepaalde tijd"], 2,
   "Lid 1 eist schriftelijkheid, een meerderjarige werknemer en een contract voor onbepaalde tijd. Het UWV speelt bij het concurrentiebeding geen rol. De rechter kan het beding wel vernietigen (lid 3).")
mc("hrm3-a07", W, A, "Een facilitair adviesbureau neemt een concurrentiebeding op in een contract voor één jaar. Wanneer is dat geldig?",
   ["Nooit, in tijdelijke contracten mag het niet", "Als in het beding schriftelijk is gemotiveerd dat het nodig is vanwege zwaarwegende bedrijfs- of dienstbelangen", "Altijd, zolang het schriftelijk is", "Alleen als de werknemer ouder is dan 25"], 1,
   "Art. 7:653 lid 2 BW: bij bepaalde tijd alleen als de werkgever in het beding motiveert dat het nodig is vanwege zwaarwegende bedrijfs- of dienstbelangen. Zonder die motivering is het beding niet geldig.")
mc("hrm3-a08", W, A, "Een schoonmaker wil in het weekend als barista werken. Zijn contract verbiedt alle nevenwerkzaamheden. Wanneer mag de werkgever zich daarop beroepen (art. 7:653a BW)?",
   ["Altijd, want het staat in het contract", "Alleen als de werkgever een objectieve rechtvaardiging heeft, zoals gezondheid, veiligheid of de Arbeidstijdenwet", "Alleen als de werknemer minder dan 20 uur werkt", "Nooit, nevenwerk mag altijd"], 1,
   "Sinds augustus 2022 geldt art. 7:653a BW: een verbod op nevenwerk (ook als zelfstandige) is alleen geldig met een objectieve rechtvaardiging. Is het gekoppeld aan toestemming, dan mag de werkgever die alleen met zo'n rechtvaardiging weigeren.")
mc("hrm3-a09", W, A, "Een werkgever wil op grond van een schriftelijk wijzigingsbeding (art. 7:613 BW) de werktijden van het hele schoonmaakteam aanpassen. Wat moet hij hebben?",
   ["Toestemming van elke werknemer apart", "Een zodanig zwaarwichtig belang dat het belang van de werknemers naar redelijkheid moet wijken", "Alleen een goede reden, zonder belangenafweging", "Toestemming van de kantonrechter"], 1,
   "Bij een wijzigingsbeding moet de werkgever een zodanig zwaarwichtig belang hebben dat het belang van de werknemer moet wijken. Zonder wijzigingsbeding kan wijzigen alleen via goed werkgeverschap en goed werknemerschap (de dubbele redelijkheidstoets).")
mc("hrm3-a10", W, A, "Wat moet er volgens art. 7:650 BW in een boetebeding staan?",
   ["Alleen dat de werkgever een boete kan opleggen", "Duidelijk waarvoor de boete geldt en hoe hoog die is, schriftelijk vastgelegd", "Een verwijzing naar de cao", "Dat de boete naar de werkgever gaat"], 1,
   "Lid 1 en 2: de overtredingen en de hoogte moeten duidelijk vermeld zijn, en het beding moet schriftelijk. Lid 3: de boete mag de werkgever niet bevoordelen. Lid 5 kent een maximale hoogte.")
mc("hrm3-a11", W, A, "Wanneer is er volgens art. 7:662 BW sprake van overgang van onderneming?",
   ["Alleen bij een fusie van twee bedrijven", "Bij de overgang van een economische eenheid die haar identiteit behoudt, bijvoorbeeld door een overeenkomst", "Als een bedrijf meer dan 50 werknemers heeft", "Alleen als de nieuwe werkgever dat zelf wil"], 1,
   "OvO is de overgang van een economische eenheid (een geheel van georganiseerde middelen voor een activiteit) die haar identiteit behoudt. Dat kan ook al bij een nieuwe aanbesteding, een nieuw schoonmaakbedrijf of een nieuwe cateraar.")
mc("hrm3-a12", W, A, "Er is sprake van overgang van onderneming. Wat geldt voor de oude werkgever?",
   ["Hij heeft geen verplichtingen meer", "Hij blijft nog één jaar naast de nieuwe werkgever aansprakelijk voor de naleving van de arbeidsovereenkomsten", "Hij moet alle werknemers een transitievergoeding betalen", "Hij blijft voor altijd de werkgever"], 1,
   "Rechten en plichten gaan van rechtswege over naar de nieuwe werkgever (art. 7:663 BW). De oude werkgever blijft nog één jaar naast de nieuwe aansprakelijk. Er geldt ook een opzegverbod wegens de overgang (art. 7:670 lid 8 BW).")

# ---------- Gespreksvoering MC ----------
mc("hrm3-g01", W, G, "Wat is volgens workshop 3 inclusie?",
   ["De verschillen in ervaringen, perspectieven en achtergronden binnen een groep", "Een werkomgeving waarin mensen gelijkwaardig kunnen deelnemen, bijdragen en zich gehoord voelen", "Een quotum voor medewerkers met een migratieachtergrond", "Iedereen op precies dezelfde manier behandelen"], 1,
   "Diversiteit zijn de verschillen binnen een groep. Inclusie is de werkomgeving waarin iedereen gelijkwaardig kan meedoen. De kern van de workshop: diversiteit is aanwezig, inclusie vraagt handelen.")
mc("hrm3-g02", W, G, "Welke uitspraak past bij 'waarnemen zonder oordeel'?",
   ["'Je bent niet betrokken bij het team.'", "'Tijdens de laatste drie overleggen heb je niets ingebracht.'", "'Ik denk dat dat in jouw cultuur zo hoort.'", "'Je bent te verlegen voor deze functie.'"], 1,
   "Je beschrijft feitelijk, waarneembaar gedrag zonder interpretatie of etiket. 'Niet betrokken' en 'te verlegen' zijn oordelen, en de opmerking over cultuur is een aanname.")
mc("hrm3-g03", W, G, "Een medewerker maakt weinig oogcontact tijdens het gesprek. Wat leer je hiervan volgens het communicatiemodel uit workshop 3?",
   ["Hij is waarschijnlijk niet geïnteresseerd", "Hij is onzeker, dus je moet hem geruststellen", "Hetzelfde gedrag kan vanuit verschillende referentiekaders anders worden gedecodeerd, bijvoorbeeld als respect", "Oogcontact zegt niets in een gesprek"], 2,
   "Weinig oogcontact kan voor de een onzeker of ongeïnteresseerd betekenen, voor de ander respectvol of aandachtig. Daarom controleer je je interpretatie in plaats van uit te gaan van je eigen referentiekader.")
mc("hrm3-g04", W, G, "Welke vraag is het best een OEN-vraag (open, eerlijk, nieuwsgierig)?",
   ["'Waarom zeg je nooit iets?'", "'Vind je de overleggen saai?'", "'Hoe ervaar jij onze overleggen?'", "'Je bent het toch wel met ons eens?'"], 2,
   "Een OEN-vraag is open en zonder verborgen oordeel. 'Waarom zeg je nooit iets' klinkt verwijtend, de andere twee zijn gesloten of suggestief.")
mc("hrm3-g05", W, G, "Wat is de eerste stap van het stappenplan 'van verschil naar werkbare afspraak'?",
   ["Het organisatiebelang benoemen", "Feitelijk gedrag benoemen", "Een concrete afspraak maken", "Een evaluatiemoment plannen"], 1,
   "De zeven stappen: feitelijk gedrag benoemen, perspectief onderzoeken, samenvatten en controleren, organisatiebelang benoemen, mogelijkheden verkennen, concrete afspraak maken en een evaluatiemoment plannen.")
mc("hrm3-g06", W, G, "Wat is de laatste stap van het stappenplan 'van verschil naar werkbare afspraak'?",
   ["Samenvatten en controleren", "Een evaluatiemoment plannen", "Het perspectief onderzoeken", "Een officiële waarschuwing geven"], 1,
   "Je sluit af met een concrete afspraak en een moment waarop je samen terugkijkt of de afspraak werkt.")
mc("hrm3-g07", W, G, "In het team is het normaal dat iedereen elkaar met 'je' aanspreekt en dat het overleg precies om 9.00 uur begint. Wat zijn dit volgens de workshop?",
   ["Waarden", "Gewoontes", "Shared values uit het 7S-model", "Wettelijke regels"], 1,
   "Gewoontes beschrijven hoe een organisatie iets nu organiseert. Waarden beschrijven wat belangrijk is (respect, veiligheid, gelijkwaardigheid). Over een gewoonte kun je makkelijker praten dan over de waarde erachter.")
mc("hrm3-g08", W, G, "Wat zegt de workshop over shared values (uit het 7S-model) en inclusie?",
   ["Gedeelde waarden leiden altijd tot inclusie", "Gedeelde waarden helpen bij inclusie, maar leiden niet vanzelf tot inclusie van minderheidsgroepen", "Shared values hebben niets met inclusie te maken", "Shared values moeten door elke medewerker zelf worden bepaald"], 1,
   "Shared values zijn algemeen aanvaarde normen die uit de missie voortkomen en het gedrag van iedereen beïnvloeden. Ze helpen, maar inclusie vraagt daarnaast handelen.")
mc("hrm3-g09", W, G, "Welke zin past het best bij de vaardigheid 'belangen verbinden'?",
   ["'Zo werkt het hier nu eenmaal.'", "'Jouw comfort is belangrijk én het team heeft jouw inhoudelijke bijdrage nodig.'", "'Als je het niet leuk vindt, moet je het zeggen.'", "'Iedereen moet zich aanpassen aan de meerderheid.'"], 1,
   "Bij belangen verbinden erken je de behoefte van de medewerker en benoem je tegelijk het organisatiebelang. Daarna verken je samen mogelijkheden.")
mc("hrm3-g10", W, G, "Een jonge medewerker reageert heel direct op feedback; een oudere collega voelde zich aangevallen. Wat is volgens de workshop de professionele aanpak?",
   ["Het gedrag verklaren vanuit de achtergrond van de medewerker", "Het concrete gedrag en het effect ervan bespreken, zonder het aan afkomst of leeftijd te koppelen", "De oudere collega vragen zich niet zo aan te stellen", "Het gesprek vermijden om het niet erger te maken"], 1,
   "Achtergrond kan gedrag beïnvloeden, maar verklaart nooit automatisch het gedrag van één persoon. Je benoemt het gedrag en het effect, onderzoekt het perspectief en maakt een afspraak.")
mc("hrm3-g11", W, G, "Wat is het motto van workshop 3 voor gesprekken over verschillen?",
   ["Eerst bijsturen, dan begrijpen", "Eerst begrijpen, dan begrenzen of bijsturen", "Verschillen zo veel mogelijk negeren", "De regels zijn voor iedereen gelijk, dus geen uitzonderingen"], 1,
   "Eerst begrijpen, dan begrenzen of bijsturen: je onderzoekt eerst het perspectief van de ander voordat je grenzen stelt of afspraken maakt.")
mc("hrm3-g12", W, G, "Een gemotiveerde medewerker uit Oekraïne maakt kleine fouten bij reserveringen en zegt: 'Sorry, ik dacht dat het anders bedoeld werd.' Wat is een goede eerste stap?",
   ["Een schriftelijke waarschuwing geven", "Onderzoeken hoe de instructies worden gegeven en of ze begrijpelijk zijn, en samen controleren wat er bedoeld werd", "Een collega vragen het werk over te nemen", "Ervan uitgaan dat het aan haar taalniveau ligt en een taalcursus regelen"], 1,
   "Het misverstand kan ook in de overdracht van de instructie zitten, niet alleen bij de medewerker. Je onderzoekt het perspectief, controleert (ANNA) en gebruikt begrijpelijke taal. Meteen een taalcursus regelen is een aanname.")

# ---------- Open vragen ----------
op("hrm3-ao1", W, A, "Aan welke eisen moet een concurrentiebeding voldoen? Bespreek contracten voor onbepaalde en voor bepaalde tijd, de rol van de rechter, en waarom de wet hier streng is.",
   "Art. 7:653 lid 1 BW: het beding moet schriftelijk zijn, met een meerderjarige werknemer, in een contract voor onbepaalde tijd. Lid 2: bij bepaalde tijd alleen als de werkgever in het beding motiveert dat het nodig is vanwege zwaarwegende bedrijfs- of dienstbelangen. Lid 3: de rechter kan het beding geheel of gedeeltelijk vernietigen als het niet noodzakelijk is of na een belangenafweging. De wet is streng omdat een concurrentiebeding de vrije arbeidskeuze beperkt (art. 19 lid 3 Grondwet).",
   ["Eisen bij onbepaalde tijd (schriftelijk, meerderjarig)", "Bij bepaalde tijd: motivering zwaarwegende belangen", "Rechter kan vernietigen (geheel of gedeeltelijk)", "Reden: vrije arbeidskeuze"])
op("hrm3-ao2", W, A, "Wat is een overgang van onderneming? Noem minstens vier factoren uit het Spijkers-arrest en leg uit wat het verschil maakt of een activiteit kapitaal- of arbeidsintensief is.",
   "Art. 7:662 BW: de overgang, door een overeenkomst, fusie of splitsing, van een economische eenheid die haar identiteit behoudt. Spijkers-factoren: de aard van de onderneming, of materiële activa worden overgedragen, de waarde van immateriële activa, of vrijwel al het personeel wordt overgenomen, of de klantenkring overgaat, hoeveel de activiteiten voor en na lijken, en hoe lang een onderbreking duurt. Je weegt ze samen. Bij een kapitaalintensieve activiteit (bussen, keukens) is de overname van de belangrijke bedrijfsmiddelen doorslaggevend. Bij een arbeidsintensieve activiteit (schoonmaak) kan de overname van een wezenlijk deel van het personeel genoeg zijn.",
   ["Juiste definitie met identiteit van de economische eenheid", "Minstens vier Spijkers-factoren", "Kapitaalintensief: bedrijfsmiddelen doorslaggevend", "Arbeidsintensief: overname personeel kan genoeg zijn"])
op("hrm3-ao3", W, A, "Een werkgever wil de werktijden van zijn medewerkers wijzigen. Leg uit hoe dat gaat met en zonder schriftelijk wijzigingsbeding.",
   "Met een schriftelijk wijzigingsbeding (art. 7:613 BW) mag de werkgever eenzijdig wijzigen als hij een zodanig zwaarwichtig belang heeft dat het belang van de werknemer naar redelijkheid moet wijken. Het beding is vooral bedoeld voor collectieve wijzigingen, zodat niet met iedereen apart onderhandeld hoeft te worden. Zonder wijzigingsbeding kan het alleen via goed werkgeverschap en goed werknemerschap: de dubbele redelijkheidstoets. Is het voorstel van de werkgever redelijk, en kan aanvaarding in redelijkheid van de werknemer worden gevergd?",
   ["Met beding: art. 7:613, schriftelijk, zwaarwichtig belang", "Zonder beding: goed werkgeverschap en werknemerschap", "Dubbele redelijkheidstoets uitgelegd"])
op("hrm3-go1", W, G, "Leg het verschil uit tussen diversiteit en inclusie en geef vier voorbeelden die laten zien dat diversiteit breder is dan afkomst.",
   "Diversiteit zijn de verschillen in ervaringen, mogelijkheden, perspectieven en achtergronden binnen een groep. Inclusie is een werkomgeving waarin mensen gelijkwaardig kunnen deelnemen, bijdragen en zich gehoord voelen: diversiteit is aanwezig, inclusie vraagt handelen. Diversiteit is breder dan afkomst: leeftijd en levensfase, opleiding, fysieke of cognitieve mogelijkheden, religie, identiteit en sociaaleconomische omstandigheden. Mensen verschillen ook in taal en woordgebruik, werkervaring, verwachtingen van leiderschap, directheid en omgang met tijd.",
   ["Juiste definitie diversiteit", "Juiste definitie inclusie", "Vier voorbeelden anders dan afkomst"])
op("hrm3-go2", W, G, "Beschrijf de zeven stappen om in een gesprek van een verschil naar een werkbare afspraak te komen.",
   "1. Benoem feitelijk gedrag. 2. Onderzoek het perspectief van de ander. 3. Vat samen en controleer. 4. Benoem het organisatiebelang. 5. Verken mogelijkheden. 6. Maak een concrete afspraak. 7. Plan een evaluatiemoment. Motto: eerst begrijpen, dan begrenzen of bijsturen.",
   ["Minstens zes stappen juist", "Logische volgorde", "Begrijpen komt vóór bijsturen"])
op("hrm3-go3", W, G, "Wat is het verschil tussen waarden en gewoontes in een organisatie? Geef van beide een facilitair voorbeeld en leg uit waarom dit onderscheid helpt in een gesprek over verschillen.",
   "Waarden beschrijven wat belangrijk is, zoals respect, veiligheid, gelijkwaardigheid of klantgerichtheid. Gewoontes beschrijven hoe de organisatie dat nu organiseert, zoals iedereen met 'je' aanspreken, overleg om precies 9.00 uur of een informele dresscode. Voorbeeld: de waarde gastvrijheid aan de receptie, met de gewoonte om bezoekers bij voornaam aan te spreken. Het onderscheid helpt omdat je over een gewoonte kunt onderhandelen, terwijl de waarde erachter overeind blijft. Zo kun je ruimte geven aan verschillen zonder het organisatiebelang los te laten.",
   ["Juiste uitleg waarden en gewoontes", "Passend FM-voorbeeld van beide", "Uitleg waarom dit helpt: gewoonte is bespreekbaar, waarde blijft"])

# ---------- Casussen ----------
cs("hrm3-ac1", W, A, "Het contract van de facilitair adviseur",
   "Noor (24) begint per 1 januari als facilitair adviseur bij adviesbureau WorkPlace. Ze krijgt een contract voor één jaar. Daarin staat:\n1. een proeftijd van twee maanden;\n2. een concurrentiebeding: Noor mag na het contract een jaar niet bij een ander facilitair adviesbureau in Nederland werken. Er staat geen toelichting bij;\n3. een verbod op alle nevenwerkzaamheden. Noor wil op zaterdag in een bakkerij werken;\n4. een boete van €1.000 bij elke overtreding van het concurrentiebeding.",
   [("Is de proeftijd van twee maanden geldig?",
     "Nee. Bij een contract van langer dan zes maanden maar korter dan twee jaar is de proeftijd maximaal één maand (art. 7:652 lid 4 BW), tenzij de cao anders regelt. Een te lange proeftijd is nietig (lid 8), dus er geldt dan helemaal geen proeftijd.",
     ["Nee, maximaal één maand bij een contract van een jaar", "Gevolg: nietig, geen proeftijd"]),
    ("Kan WorkPlace zich op het concurrentiebeding beroepen?",
     "Waarschijnlijk niet. Bij een contract voor bepaalde tijd is een concurrentiebeding alleen geldig als de werkgever in het beding motiveert dat het nodig is vanwege zwaarwegende bedrijfs- of dienstbelangen (art. 7:653 lid 2 BW). Die motivering ontbreekt. Daardoor heeft ook de boete op overtreding van dit beding geen basis.",
     ["Nee, bepaalde tijd zonder motivering", "Art. 7:653 lid 2 en de zwaarwegende belangen genoemd"]),
    ("Mag WorkPlace Noor het werk in de bakkerij verbieden?",
     "Alleen met een objectieve rechtvaardiging (art. 7:653a BW), bijvoorbeeld gezondheid, veiligheid, de Arbeidstijdenwet of vertrouwelijke bedrijfsinformatie. Werken in een bakkerij op zaterdag raakt het adviesbureau waarschijnlijk niet, dus een algemeen verbod is hier waarschijnlijk niet te rechtvaardigen.",
     ["Objectieve rechtvaardiging nodig (art. 7:653a)", "Toepassing: bij de bakkerij waarschijnlijk geen rechtvaardiging"])])
cs("hrm3-ac2", W, A, "Nieuw schoonmaakbedrijf na de aanbesteding",
   "Hogeschool Rijnstad heeft de schoonmaak opnieuw aanbesteed. Het contract gaat van SchoonPlus naar CleanCo. CleanCo neemt 18 van de 20 schoonmakers over die al jaren op de hogeschool werken, maar brengt eigen machines en middelen mee. CleanCo wil de overgenomen schoonmakers een nieuw contract geven met minder vakantiedagen dan ze bij SchoonPlus hadden. Ook wil CleanCo twee schoonmakers direct ontslaan 'omdat er bij de overname te veel mensen zijn gekomen'.",
   [("Is er sprake van overgang van onderneming? Motiveer met de definitie en de factoren.",
     "Waarschijnlijk wel. Art. 7:662 BW: een economische eenheid (de schoonmaak van de hogeschool) gaat door een overeenkomst over en behoudt haar identiteit. Schoonmaak is arbeidsintensief. Dan kan de overname van een wezenlijk deel van het personeel genoeg zijn, ook als machines en middelen niet overgaan. 18 van de 20 is een wezenlijk deel, en de activiteit op dezelfde locatie blijft gelijk (Spijkers-factoren).",
     ["Definitie art. 7:662 toegepast", "Arbeidsintensief, dus overname personeel weegt zwaar", "Conclusie: waarschijnlijk OvO"]),
    ("Mag CleanCo de schoonmakers minder vakantiedagen geven?",
     "Nee, niet zomaar. Bij OvO gaan de rechten en plichten uit de arbeidsovereenkomsten van rechtswege over op de nieuwe werkgever (art. 7:663 BW). De schoonmakers behouden dus hun arbeidsvoorwaarden. SchoonPlus blijft nog een jaar naast CleanCo aansprakelijk voor de naleving.",
     ["Rechten en plichten gaan over (art. 7:663)", "Oude werkgever een jaar aansprakelijk"]),
    ("Mag CleanCo twee schoonmakers ontslaan vanwege de overname?",
     "Nee. Er geldt een opzegverbod wegens de overgang van onderneming (art. 7:670 lid 8 BW). CleanCo mag niet opzeggen omdat er een overgang is geweest.",
     ["Opzegverbod wegens OvO (art. 7:670 lid 8)"])])
cs("hrm3-gc1", W, G, "Een medewerker die niets inbrengt",
   "Je bent teamleider facilitaire dienst. Medewerker Wei werkt nauwkeurig en is altijd op tijd. In het wekelijkse teamoverleg zegt hij alleen 'Dat is goed' of 'Zoals jij wilt'. Twee collega's hebben bij jou geklaagd dat Wei 'niet betrokken' is. Je wilt zijn kennis van de nieuwe roostersoftware juist graag benutten in het overleg. Je plant een gesprek met hem.",
   [("Hoe open je het gesprek? Formuleer je eerste twee zinnen en leg uit waarom.",
     "Bijvoorbeeld: 'Ik wil het graag met je hebben over het teamoverleg. Het viel me op dat je in de laatste drie overleggen vooral hebt gezegd dat het goed is, en verder weinig hebt ingebracht.' Je benoemt feitelijk gedrag zonder oordeel (dus niet 'je bent niet betrokken') en noemt het onderwerp meteen, zodat het gesprek veilig en duidelijk start.",
     ["Feitelijk gedrag zonder oordeel of etiket", "Doel van het gesprek benoemd", "Uitleg waarom (geen aanname, geen verwijt)"]),
    ("Welke vragen stel je om zijn perspectief te onderzoeken, en hoe controleer je of je hem goed begrijpt?",
     "OEN-vragen zoals 'Hoe ervaar jij onze overleggen?' en 'Wat zou helpen om jouw kennis beter in te brengen?' Daarna samenvatten en controleren (LSD en ANNA): 'Als ik je goed begrijp, vind je het lastig om in een grote groep te reageren en wil je liever vooraf weten welke onderwerpen er komen. Klopt dat?'",
     ["Minstens twee open, nieuwsgierige vragen", "Een samenvatting met controlevraag"]),
    ("Hoe sluit je af zodat er een werkbare afspraak ligt?",
     "Verbind de belangen ('Jouw comfort is belangrijk én het team heeft jouw kennis van de roostersoftware nodig'), verken samen mogelijkheden (agenda vooraf, een vast agendapunt waarin hij een korte update geeft, eerst in een kleiner groepje) en maak een concrete afspraak: wie doet wat en wanneer. Plan een evaluatiemoment, bijvoorbeeld over vier weken.",
     ["Belangen verbinden (individu en organisatie)", "Concrete afspraak", "Evaluatiemoment gepland"])])
